// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // fuzz parameters: an address to receive and an uint array length/values encoded via a single uint
    // We'll fuzz a single recipient and a single value by packing into the fuzzer params.
    function setUp() public { c = new C(); }

    // We fuzz one recipient and one value. The general rule: when transfer returns (does not revert),
    // reference returns true. We observe the return via try/catch to get a boolean 'ok' indicating non-revert
    // and then call the function via low-level call to capture the returned bool value.
    function testFuzz_property(address to, uint256 v) public {
        // keep to non-zero to satisfy reference require(_tos.length > 0) indirectly by constructing arrays
        vm.assume(to != address(0));

        // Construct arrays with one element each
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v;

        // Ensure msg.sender matches the hard-coded allowed sender in C
        address allowed = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(allowed);

        // Call via try/catch to detect revert vs non-revert
        bool nonReverted;
        try c.transfer(tos, vals) {
            nonReverted = true;
        } catch {
            nonReverted = false;
        }

        // If the call reverted, we cannot observe a returned bool; the universal property only applies to non-reverting calls.
        // So we only assert when the call did NOT revert: then the reference must have returned true.
        if (nonReverted) {
            // Re-call with low-level call to read the returned boolean value from the external call
            (bool success, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, vals));
            // success should be true because we already observed nonReverted above
            // decode return value
            bool returned = false;
            if (ret.length >= 32) {
                returned = abi.decode(ret, (bool));
            }
            // The general rule: for any non-reverting invocation, the reference contract returns true.
            assertTrue(returned);
        } else {
            // if reverted, nothing to assert about return value; trivially hold
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the recipient address and an amount. We must ensure admissible domain:
    // - caller must be the allowed from address hardcoded in C
    // - _tos.length > 0, so we construct a single-element array
    // - v[0] must either be 0 or such that (v*1e18)/v == 1e18, which holds for any v > 0
    //   because multiplication by 1e18 then integer divide by v returns 1e18 iff no overflow
    //   and v divides (v*1e18) exactly; to keep wide, we simply bound v to a small non-zero
    //   range where multiplication does not overflow (v <= type(uint).max / 1e18).
    function testFuzz_property(address to, uint256 v0) public {
        // restrict caller to the required address in contract C
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

        // admissible: to must be non-zero (but contract accepts any address in array),
        // ensure _tos.length > 0 by using single element array below.
        // bound v0 to avoid overflow when multiplying by 1e18
        uint256 maxSafe = type(uint256).max / 1000000000000000000;
        v0 = bound(v0, 0, maxSafe);

        // construct single-element arrays as the function expects
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v0;

        // Call transfer as the required caller. We capture the return value via try/catch
        // to observe the bool returned by the external call. The reference implementation
        // guarantees that for any admissible inputs that do not revert, it returns true.
        bool ok;
        vm.prank(caller);
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, mark ok as false (but admissible inputs should allow non-revert too)
            ok = false;
        }

        // The reference C returns true for EVERY admissible non-reverting call; the mutant
        // returns false for some non-reverting calls. We assert that the observed return
        // value is true. This will pass on the reference for all admissible inputs and
        // fail on the mutant for some input the fuzzer finds.
        assertTrue(ok);
    }
}
